// Marketing materials for a paid property package — built entirely from the customer's own
// approved property content.
//
// Two deliberate design decisions keep this cheap and honest:
//   * nothing is generated by an AI model at request time. Captions are deterministic templates
//     over approved fields and graphics are rendered in the customer's browser from the approved
//     photographs, so opening the panel costs no integration credits and repeatedly downloading the
//     same asset costs nothing at all.
//   * every sentence is assembled from fields the customer already approved. Nothing is invented:
//     no feature, no dimension, no school, no neighbourhood, no "open house", no promise of
//     traffic, ranking, leads or results. Anything not present in the listing is simply absent.

import { mediaStreamUrl, propertyPageUrl } from "./propertyVisibility.ts";
import {
  ADVERTISING_UNAVAILABLE_NOTE,
  REFUND_DISCLOSURE,
  isPaidTier,
} from "./propertyPackages.ts";

function money(value: any): string {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return "";
  return `$${n.toLocaleString("en-US", { maximumFractionDigits: 0 })}`;
}

function titleCase(value: string): string {
  return String(value || "").replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

function locationLine(listing: any): string {
  return [listing?.city, listing?.state].filter(Boolean).join(", ");
}

function factsLine(listing: any): string {
  const parts: string[] = [];
  if (listing?.bedrooms != null) parts.push(`${listing.bedrooms} bed`);
  if (listing?.bathrooms != null) parts.push(`${listing.bathrooms} bath`);
  if (listing?.square_footage != null) parts.push(`${Number(listing.square_footage).toLocaleString("en-US")} sq ft`);
  if (listing?.property_type) parts.push(titleCase(listing.property_type));
  return parts.join(" · ");
}

function statusPhrase(listing: any): string {
  const status = String(listing?.listing_status || "active");
  if (status === "pending") return "Sale pending";
  if (status === "sold") return "Sold";
  return "For sale";
}

function credit(listing: any): string {
  const agent = String(listing?.agent_name || "").trim();
  const brokerage = String(listing?.brokerage_name || "").trim();
  if (agent && brokerage) return `${agent} · ${brokerage}`;
  return agent || brokerage || "";
}

export function marketingCampaignName(listing: any, tier: string): string {
  return `${String(listing?.public_slug || listing?.listing_id || "property")}-${String(tier || "free")}`;
}

// Tracked destination links. The attribution the page already records (channel, source, campaign)
// is what these tags land in, so a click from Facebook is visible in the report without any new
// tracking infrastructure.
export function marketingLinks(listing: any, tier: string) {
  const page = propertyPageUrl(listing?.public_slug || "");
  const campaign = marketingCampaignName(listing, tier);
  const tag = (source: string, medium: string) =>
    `${page}?utm_source=${encodeURIComponent(source)}&utm_medium=${encodeURIComponent(medium)}&utm_campaign=${encodeURIComponent(campaign)}`;

  const links = [
    { key: "page", label: "Public property page", url: page, kind: "direct" },
    { key: "facebook", label: "Facebook post link", url: tag("facebook", "social"), kind: "social" },
    { key: "instagram", label: "Instagram bio link", url: tag("instagram", "social"), kind: "social" },
    { key: "email", label: "Email / newsletter link", url: tag("email", "referral"), kind: "referral" },
  ];
  if (String(tier) === "pro") {
    links.push(
      { key: "google", label: "Paid search landing link", url: tag("google", "cpc"), kind: "paid" },
      { key: "qr", label: "Print / sign rider link", url: tag("print", "referral"), kind: "referral" },
    );
  }
  return { campaign, links };
}

export function buildCaptions(listing: any, tier: string) {
  const address = String(listing?.property_address || "This property").trim();
  const place = locationLine(listing);
  const price = money(listing?.listing_price);
  const facts = factsLine(listing);
  const creditLine = credit(listing);
  const links = marketingLinks(listing, tier);
  const page = links.links[0].url;
  const status = statusPhrase(listing);

  const heading = place ? `${address}, ${place}` : address;
  const priceLine = price ? `Offered at ${price}.` : "";
  const factsSentence = facts ? `${facts}.` : "";
  const creditSentence = creditLine ? `Listed with ${creditLine}.` : "";

  const base = [
    heading,
    `${status}.`,
    priceLine,
    factsSentence,
    creditSentence,
    `Photography by Arriv Estate Media. Full details and photos: ${page}`,
    "#realestate #property #homesforsale",
  ].filter(Boolean).join("\n");

  const short = [heading, priceLine, `${status}.`, page].filter(Boolean).join("\n");

  const captions = [
    { key: "plus_primary", label: "Facebook / Instagram — primary", channel: "social", text: base },
    { key: "plus_short", label: "Instagram — short caption", channel: "social", text: short },
  ];

  if (tier === "pro") {
    const factsFocused = [
      `${heading} is ${status.toLowerCase()}.`,
      factsSentence,
      priceLine,
      creditSentence,
      `Take a full look: ${page}`,
      "#justlisted #househunting #realestate",
    ].filter(Boolean).join("\n");

    const photoFocused = [
      `A closer look at ${heading}.`,
      factsSentence,
      priceLine,
      `Every photograph in this gallery was taken by our team. See the whole set: ${page}`,
      creditSentence,
      "#homephotography #realestatephotography #propertytour",
    ].filter(Boolean).join("\n");

    const agentFocused = [
      `${heading} — ${status.toLowerCase()}.`,
      creditSentence,
      priceLine,
      factsSentence,
      `Details, photos and a direct way to ask a question: ${page}`,
      "#realestateagent #listingagent #dreamhome",
    ].filter(Boolean).join("\n");

    const emailSubject = price
      ? `${address}${place ? `, ${place}` : ""} — ${price}`
      : `${address}${place ? `, ${place}` : ""}`;

    captions.push(
      { key: "pro_facts", label: "Facts-led caption", channel: "social", text: factsFocused },
      { key: "pro_gallery", label: "Photography-led caption", channel: "social", text: photoFocused },
      { key: "pro_agent", label: "Agent-led caption", channel: "social", text: agentFocused },
      { key: "pro_email", label: "Email subject line", channel: "email", text: emailSubject },
    );
  }

  return captions;
}

// Graphic specifications. The customer's browser renders these from the approved cover photograph
// and downloads them as PNG — no AI generation, no image library, no cost per download.
export function buildGraphics(listing: any, tier: string) {
  const address = String(listing?.property_address || "").trim();
  const place = locationLine(listing);
  const price = money(listing?.listing_price);
  const facts = factsLine(listing);
  const creditLine = credit(listing);
  const cover = listing?.cover_file_id
    ? mediaStreamUrl(listing.listing_id, listing.cover_file_id)
    : "";
  const disclosure = "Arriv Estate Media · No guarantee of results";

  const shapes = [
    { key: "square", label: "Square post (1080×1080)", width: 1080, height: 1080, layout: "portrait" },
    { key: "story", label: "Story / reel cover (1080×1920)", width: 1080, height: 1920, layout: "story" },
    { key: "landscape", label: "Facebook link card (1200×630)", width: 1200, height: 630, layout: "landscape" },
  ];

  const allowed = tier === "pro" ? shapes : shapes.slice(0, 2);

  return allowed.map((shape) => ({
    ...shape,
    headline: address,
    subheadline: place,
    price_line: price,
    facts_line: facts,
    credit_line: creditLine,
    cover_url: cover,
    badge: String(tier) === "pro" ? "Priority" : "Featured",
    footer: "Photographed and delivered by Arriv Estate Media",
    disclosure,
  }));
}

// Pro's campaign preparation. This is preparation only: it names what a compliant campaign would
// look like and states plainly that buying and running ads is not included and not connected.
export function buildCampaignPlan(listing: any, tier: string) {
  if (String(tier) !== "pro") return { available: false };

  const place = locationLine(listing);
  const links = marketingLinks(listing, "pro");
  const captions = buildCaptions(listing, "pro");

  return {
    available: true,
    objective: place
      ? `Local buyer awareness for a property in ${place}`
      : "Local buyer awareness for this property",
    integrations: [
      {
        provider: "meta_ads",
        label: "Meta (Facebook / Instagram) Ads",
        status: "disabled",
        note: "Not connected. Buying, publishing or managing Meta ads requires a separate agreement and an authorised advertising account.",
      },
      {
        provider: "google_ads",
        label: "Google Ads",
        status: "disabled",
        note: "Not connected. Google Ads is not part of any package and no spend is included or managed by Arriv.",
      },
    ],
    geography: {
      city: listing?.city || "",
      state: listing?.state || "",
      zip: listing?.zip || "",
      suggestion: listing?.zip
        ? `Start from the ${listing.zip} area and widen only as far as the agent can justify.`
        : "Set the geography from the property's own location with the listing agent.",
      note: "Geography must be set by the listing agent. Housing campaigns may not target by race, colour, religion, sex, disability, familial status or national origin, or use proxies for them.",
    },
    structure: [
      {
        stage: "Awareness",
        audience: "Broad local audience around the property, defined by location only",
        creative: "Square post graphic + facts-led caption",
        note: "Housing campaigns on Meta require the Special Ad Category: Housing setting.",
      },
      {
        stage: "Engagement",
        audience: "People who opened or engaged with the property page",
        creative: "Story graphic + photography-led caption",
        note: "Retargeting audiences must also respect the housing special category rules.",
      },
      {
        stage: "Direct",
        audience: "The agent's own audience and the listing's tracked links",
        creative: "Email subject line + tracked links",
        note: "No ad spend: this is the customer's own distribution.",
      },
    ],
    budget: {
      currency: "USD",
      note: "Advertising spend is set and paid by the customer directly with the provider. Arriv does not fund, quote, collect or manage ad spend, and no spend is included in the package price.",
      guidance: "Choose any daily budget you are comfortable with. Nothing in this package depends on advertising spend.",
    },
    compliance: [
      "Advertise without discrimination on the basis of race, colour, religion, sex, disability, familial status or national origin (Fair Housing Act).",
      "Do not target audiences by protected characteristics or by proxies for them.",
      "Use the Special Ad Category: Housing setting where the provider requires it.",
      "Include the listing agent's name and brokerage, and the licence number where the jurisdiction requires it.",
      "Make no claim about future value, school quality, neighbourhood composition or investment return.",
      "No package, report or material guarantees traffic, ranking, leads, impressions or advertising results.",
    ],
    copy_options: captions.filter((c) => c.channel === "social").map((c) => ({ label: c.label, text: c.text })),
    tracked_links: links.links,
    campaign_name: links.campaign,
    disclaimer: ADVERTISING_UNAVAILABLE_NOTE,
  };
}

export function buildMarketingPackage(listing: any, tier: string) {
  const paid = isPaidTier(tier);
  return {
    tier: paid ? String(tier) : "free",
    paid,
    page_url: propertyPageUrl(listing?.public_slug || ""),
    links: marketingLinks(listing, tier),
    captions: paid ? buildCaptions(listing, tier) : [],
    graphics: paid ? buildGraphics(listing, tier) : [],
    campaign: paid ? buildCampaignPlan(listing, tier) : { available: false },
    disclosures: [REFUND_DISCLOSURE, ADVERTISING_UNAVAILABLE_NOTE],
    generated_from: "approved_listing_content",
  };
}